-- KIA PIECE schema. Applied first to isolated Neon branch kia-piece-dev.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),full_name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,phone TEXT,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'customer' CHECK(role IN ('customer','admin')),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS categories (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name TEXT NOT NULL UNIQUE,slug TEXT NOT NULL UNIQUE,description TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS vehicles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),make TEXT NOT NULL DEFAULT 'Kia',model TEXT NOT NULL,year_from SMALLINT,year_to SMALLINT,engine TEXT,generation TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(model,year_from,year_to,engine));
CREATE TABLE IF NOT EXISTS products (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),sku TEXT NOT NULL UNIQUE,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,description TEXT NOT NULL DEFAULT '',category_id UUID REFERENCES categories(id) ON DELETE SET NULL,price NUMERIC(12,2) NOT NULL CHECK(price>=0),currency CHAR(3) NOT NULL DEFAULT 'EUR',stock_quantity INTEGER NOT NULL DEFAULT 0 CHECK(stock_quantity>=0),condition TEXT NOT NULL DEFAULT 'new' CHECK(condition IN('new','used','refurbished')),image_url TEXT,is_active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS product_compatibility (product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE,vehicle_id UUID NOT NULL REFERENCES vehicles(id) ON DELETE CASCADE,notes TEXT,PRIMARY KEY(product_id,vehicle_id));
CREATE TABLE IF NOT EXISTS orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),order_number TEXT NOT NULL UNIQUE,user_id UUID REFERENCES users(id) ON DELETE SET NULL,customer_name TEXT NOT NULL,customer_email TEXT NOT NULL,customer_phone TEXT NOT NULL,shipping_address JSONB NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','confirmed','processing','shipped','delivered','cancelled')),subtotal NUMERIC(12,2) NOT NULL CHECK(subtotal>=0),shipping_fee NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK(shipping_fee>=0),total NUMERIC(12,2) NOT NULL CHECK(total>=0),currency CHAR(3) NOT NULL DEFAULT 'EUR',notes TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS order_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),order_id UUID NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id UUID REFERENCES products(id) ON DELETE SET NULL,sku TEXT NOT NULL,product_name TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),unit_price NUMERIC(12,2) NOT NULL CHECK(unit_price>=0),line_total NUMERIC(12,2) NOT NULL CHECK(line_total>=0));
CREATE TABLE IF NOT EXISTS inquiries (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name TEXT NOT NULL,email TEXT NOT NULL,phone TEXT,subject TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'new' CHECK(status IN('new','in_progress','resolved')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS products_active_category_idx ON products(is_active,category_id);
CREATE INDEX IF NOT EXISTS products_name_search_idx ON products USING GIN(to_tsvector('simple',name||' '||sku||' '||description));
CREATE INDEX IF NOT EXISTS orders_created_at_idx ON orders(created_at DESC);
CREATE INDEX IF NOT EXISTS orders_user_idx ON orders(user_id,created_at DESC);
INSERT INTO categories(name,slug,description) VALUES('Moteur','moteur','Pièces moteur et périphériques'),('Freinage','freinage','Disques, plaquettes et composants de freinage'),('Filtration','filtration','Filtres à huile, air, carburant et habitacle'),('Carrosserie','carrosserie','Éléments extérieurs et carrosserie'),('Électricité','electricite','Éclairage, capteurs et composants électriques'),('Suspension','suspension','Amortisseurs, bras et direction') ON CONFLICT(slug) DO NOTHING;